create function pg_temp.fail_reopening_event() returns trigger language plpgsql as $$ begin if new.event_type='reopened' then raise exception 'forced event failure'; end if; return new; end $$;
create trigger test_reopening_atomicity before insert on public.task_events for each row execute function pg_temp.fail_reopening_event();
